Here's an example of how you can convert a std::string containing markdown formatted text to html using C++:

```
#include <iostream>
#include <string>
#include <sstream>
#include <vector>

using namespace std;

// Convert a std::string containing markdown formatted text to html
string markdown_to_html(const std::string& markdown)
{
    // Parse markdown into individual lines
    vector<string> lines;
    stringstream(markdown) >> lines;

    // Construct an html document
    string html = "<html><body>";
    for (const auto& line : lines) {
        html += "<p>" + line + "</p>";
    }
    html += "</body></html>";

    // Return the html document
    return html;
}

int main()
{
    // Create a std::string containing markdown formatted text
    string markdown = "# Hello, this is a markdown document\n"
                       "## Table of contents\n"
