                       "|--1. First point --|--2. Second point--|\n"
                       "| Point 3 | Point 4 |\n"
                       "|--3. Third point --|--4. Fourth point--|\n"
                       "| Point 5 | Point 6 |\n"
                       "|--5. Fifth point --|--6. Sixth point--|\n"
                       "|. Conclusion.|";

    // Call the markdown_to_html function
    string html = markdown_to_html(markdown);

    // Display the html document
    cout << html << endl;

    return 0;
}
