```
#include <SDL.h>
#include <stdio.h>

int main(int argc, char* argv[]) {

    // Initialize SDL
    if (SDL_Init(SDL_INIT_EVERYTHING)!= 0) {
        printf("SDL initialization failed!\n");
        return -1;
    }

    // Create a window
    SDL_Window* window = SDL_CreateWindow("Snake Game",
                                             SDL_WINDOWPOS_CENTERED,
                                             SDL_WINDOWPOS_CENTERED,
                                             640,
                                              480,
                                             SDL_WINDOW_SHOWN);

    // Create a snake
    Snake* snake = Snake::create();

    // Create a food
    Food* food = Food::create();

    // Set the speed of the snake
    snake->setSpeed(20);

    // Fill the snake's body
    while (true) {
        // Get the input from the user
        char input;
        do {
            input = getchar();
        } while (input =='' || input == '\t' || input == '\n' || input == '\r');

        // Update the snake's position
        snake->update(input);

        // Draw the snake and the food on the screen
        SDL_RenderClear(window);
        Snake::draw(snake, window);
        Food::draw(food, window);

        // Check if the snake has hit a wall
        if (snake->hasHitWall()) {
            // Make the snake die
            snake->die();
        }

        // Check if the snake has eaten the food
        if (snake->hasEatenFood()) {
            // Make the snake grow
            snake->grow();
        }

        // Wait for a key press
        SDL_WaitEvent(window);
    }

    // Clean up SDL
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
